function bossesForRun(){return run?.mode==='gauntlet'?GAUNTLET_BOSSES:run?.mode==='rift'?RIFT_BOSSES:MAX_BOSSES}
function activeRiftModifiers(){if(run?.mode!=='rift')return[];const count=Math.floor(run.riftTier/5);return Array.from({length:count},(_,i)=>RIFT_MODIFIERS[i%RIFT_MODIFIERS.length].id)}
function difficultyUnlockWins(level){return [0,1,3,6,10,15,20][clamp(Math.floor(level),0,DIFFICULTIES.length-1)]||0}
function difficultyUnlocked(){return clamp([0,1,3,6,10,15,20].findLastIndex((n)=>meta.wins>=n),0,DIFFICULTIES.length-1)}
function activeRunModifiers(level=run?.difficulty??meta.difficulty){const diff=clamp(level||0,0,DIFFICULTIES.length-1);if(run?.mode==='rift')return activeRiftModifiers();const count=DIFFICULTIES[diff]?.modifiers||0;const offset=((run?.map??meta.selectedMap)+Math.max(0,diff-2))%RUN_MODIFIERS.length;return Array.from({length:count},(_,i)=>RUN_MODIFIERS[(offset+i)%RUN_MODIFIERS.length].id)}
function difficultyStats(){const d=DIFFICULTIES[clamp(run?.difficulty??meta.difficulty??0,0,DIFFICULTIES.length-1)]||DIFFICULTIES[0];return {hp:run?.mode==='rift'?1+Math.max(0,(run.riftTier||1)-1)*.12:d.hp,damage:run?.mode==='rift'?1+Math.max(0,(run.riftTier||1)-1)*.07:d.damage,elite:run?.mode==='rift'?Math.min(.45,.08+(run.riftTier||1)*.01):d.elite,loot:run?.mode==='rift'?1+(run.riftTier||1)*.1:d.loot}}
