function isoWeekKey(date=new Date()){
 const d=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()));
 d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));
 const year=d.getUTCFullYear(),start=new Date(Date.UTC(year,0,1));
 const week=Math.ceil((((d-start)/86400000)+1)/7);
 return `${year}-W${String(week).padStart(2,'0')}`;
}
function weeklyChallenge(key=isoWeekKey()){
 const [year,week]=key.split('-W').map(Number);
 const index=(year+week)%WEEKLY_MODIFIERS.length,banned=[['meteor','orbs'],['fireball','soul'],['chain','orbs']][(year*7+week)%3];
 return {key,modifier:WEEKLY_MODIFIERS[index],modifier2:WEEKLY_MODIFIERS[(index+1)%WEEKLY_MODIFIERS.length],classId:'arcanist',bannedSkills:banned};
}
function weeklyHas(id){return run?.mode==='weekly'&&(run.weeklyModifier===id||run.weeklyModifier2===id)}
function weeklySeed(key){let seed=2166136261;for(let i=0;i<key.length;i++)seed=Math.imul(seed^key.charCodeAt(i),16777619);return (seed>>>0)||1}
function gameRandom(){if(run?.mode==='weekly'&&run.rngState){let t=run.rngState=(run.rngState+0x6D2B79F5)>>>0;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}return Math.random()}
