function bossArrival(){return activeRunModifiers().includes('timePressure')?BOSS_INTERVAL*.8:run?.mode==='gauntlet'?45:BOSS_INTERVAL}
function lootWeights(mapIndex=0,tier=1,boost=0){const source=LOOT_TABLES[clamp(mapIndex,0,MAPS.length-1)][clamp(tier-1,0,2)],ret=RARITIES.map(r=>({...r,weight:source[r.id]||0})),ancient=ret.find(r=>r.id==='ancient'),mythic=ret.find(r=>r.id==='mythic');if(ancient)ancient.weight=mapIndex>=2?(mapIndex===2?.2:mapIndex===3?.5:mapIndex===4?1:1.5):0;if(mythic)mythic.weight=run?.mode==='rift'&&run.riftTier>=10?Math.min(5,(run.riftTier-9)*.35):0;if(run&&run.mode!=='weekly'){const bonus=Math.max(0,difficultyStats().loot-1);for(const id of ['rare','epic','legendary','ancient','mythic']){const x=ret.find(r=>r.id===id);if(x)x.weight*=1+bonus+(meta.transcendence?.fortune||0)*.03}}if(boost){for(const [id,mult]of [['rare',1.45],['epic',1.6],['legendary',1.8],['ancient',1.8],['mythic',1.8]]){const x=ret.find(r=>r.id===id);if(x)x.weight*=mult}}return ret;}
