const cv=$('game'),ctx=cv.getContext('2d',{alpha:false});
const VIEW_WIDTH=480,VIEW_HEIGHT=300;
// Render into the physical display resolution. Never resize a 960x600 bitmap via CSS.
// CSS size and DPR may change when the player docks the window beside an editor.
function resizeGameCanvas(){
 const bounds=cv.getBoundingClientRect();
 if(!bounds.width||!bounds.height)return;
 const dpr=Math.min(2,Math.max(1,window.devicePixelRatio||1));
 const w=Math.max(1,Math.round(bounds.width*dpr)),h=Math.max(1,Math.round(bounds.height*dpr));
 if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;}
 ctx.setTransform(cv.width/VIEW_WIDTH,0,0,cv.height/VIEW_HEIGHT,0,0);
 ctx.imageSmoothingEnabled=true;
 ctx.imageSmoothingQuality='high';
}
resizeGameCanvas();
if(typeof ResizeObserver!=='undefined')new ResizeObserver(resizeGameCanvas).observe($('canvasHolder'));
window.addEventListener('resize',resizeGameCanvas);
