const HERO_HIT_RADIUS=16, HERO_HIT_OFFSET_Y=-16;
function heroHit(){return {x:run.x,y:run.y+HERO_HIT_OFFSET_Y,r:HERO_HIT_RADIUS}}
function mobHit(m){return {x:m.x,y:m.y-(m.type==='boss'?10:9),r:m.r+(m.type==='boss'?3:1)}}
const MOB_GRID_CELL=96;
function rebuildMobGrid(){mobGrid.clear();for(const m of mobs){if(m.hp<=0)continue;const key=`${Math.floor(m.x/MOB_GRID_CELL)},${Math.floor(m.y/MOB_GRID_CELL)}`;if(!mobGrid.has(key))mobGrid.set(key,[]);mobGrid.get(key).push(m)}}
function nearbyMobGrid(x1,y1,x2,y2,radius=40){const found=[];for(let gx=Math.floor((Math.min(x1,x2)-radius)/MOB_GRID_CELL);gx<=Math.floor((Math.max(x1,x2)+radius)/MOB_GRID_CELL);gx++)for(let gy=Math.floor((Math.min(y1,y2)-radius)/MOB_GRID_CELL);gy<=Math.floor((Math.max(y1,y2)+radius)/MOB_GRID_CELL);gy++){const cell=mobGrid.get(`${gx},${gy}`);if(cell)found.push(...cell)}return found}
function sweptCircleHit(x1,y1,x2,y2,cx,cy,r){
 const dx=x2-x1,dy=y2-y1,l2=dx*dx+dy*dy;
 const u=l2>1e-8?Math.max(0,Math.min(1,((cx-x1)*dx+(cy-y1)*dy)/l2)):0;
 const px=x1+u*dx-cx,py=y1+u*dy-cy;
 return px*px+py*py<=r*r;
}

// v0.7 original transparent PNG sprite atlas. The code-drawn actors remain as fallback.
const SPRITE_CELL=128, SPRITE_ROWS={mage:0,goblin:1,spider:2,mushroom:3,cultist:4,skeleton:5,wraith:6,bat:7,scorpion:8,raider:9,ent:10,lich:11,colossus:12,pine:13,grave:14,torch:15,rock:16,bush:17};
const spriteAtlas=new Image();let spriteReady=false;
spriteAtlas.onload=()=>{spriteReady=true;};
spriteAtlas.onerror=()=>{console.warn('Sprite atlas nelze načíst; používám záložní kreslení.');};
spriteAtlas.src='assets/sprite_atlas.png';
function drawAtlasSprite(id,frame,x,y,w,h,alpha=1){
 if(!spriteReady||!Number.isFinite(x)||!Number.isFinite(y)||!(id in SPRITE_ROWS))return false;
 const sx=(frame%4)*SPRITE_CELL, sy=SPRITE_ROWS[id]*SPRITE_CELL;
 ctx.save();ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.globalAlpha*=alpha;
 // Anchor: rendered character feet around world y + 0.20 * sprite height.
 ctx.drawImage(spriteAtlas,sx,sy,SPRITE_CELL,SPRITE_CELL,Math.round(x-w/2),Math.round(y-h*.77),w,h);
 ctx.restore();return true;
}
function spriteForMob(m,map){
 if(m.type==='boss')return map.id==='forest'?'ent':map.id==='crypt'?'lich':map.id==='frost'?'wraith':map.id==='caldera'?'colossus':map.id==='astral'?'lich':'colossus';
 if(map.id==='forest')return m.type==='runner'?'spider':m.type==='caster'?'cultist':m.type==='brute'?'mushroom':'goblin';
 if(map.id==='crypt')return m.type==='runner'?'bat':m.type==='caster'?'wraith':'skeleton';
 if(map.id==='frost')return m.type==='runner'?'spider':m.type==='caster'?'wraith':m.type==='brute'?'mushroom':'goblin';
 if(map.id==='caldera')return m.type==='runner'?'scorpion':m.type==='caster'?'cultist':m.type==='brute'?'colossus':'raider';
 if(map.id==='astral')return m.type==='runner'?'wraith':m.type==='caster'?'lich':m.type==='brute'?'colossus':'cultist';
 return m.type==='runner'?'scorpion':m.type==='caster'?'cultist':'raider';
}
