function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const data=JSON.parse(raw);importSave(data);applyOffline((Date.now()-Number(data.savedAt||Date.now()))/1000);save(true);return}}catch(err){console.warn('Uložená hra se nepodařila načíst:',err)}const starter=makeItem(1);starter.name='Učednická hůl';starter.rarity='common';starter.stats={atk:3};starter.slot='weapon';starter.level=1;meta.inventory.push(starter);meta.equipped.weapon=starter.id;log('Vítej ve světě Chronicles of the Rift.');save(true)}
function openModal(title,content,eyebrow='KRONIKA'){activePanel=eyebrow==='NOVÁ ÚROVEŇ'?'draft':title;$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalContent').innerHTML=content;const modal=$('modalBackdrop').querySelector('.modal');modal.classList.toggle('inventory-modal',eyebrow==='VÝBAVA A LOOT');modal.classList.toggle('card-grid-modal',['PRESTIGE','MISTROVSTVÍ','POSTAVA','TRŽNICE','OSOBNÍ CÍLE','SBÍRKA','KOUZLA'].includes(eyebrow));$('modalBackdrop').classList.remove('hidden');$('modalClose').style.display=activePanel==='draft'?'none':''}
function hideModal(force=false){if(!force&&activePanel==='draft'&&run?.active)return;$('modalBackdrop').classList.add('hidden');activePanel=null}
function closePanel(){if(activePanel==='draft'){const opts=Array.from(document.querySelectorAll('[data-skill]')).map(n=>n.dataset.skill);if(opts.length)autoPick(opts);return}hideModal();if(run?.ended)showIntro('Výprava skončila','Výbava a zkušenosti zůstávají. Začni další výpravu s novou kombinací schopností.','⚔ Nový run')}
function openDraft(offers){const cards=offers.map(id=>{const s=SKILLS[id],lvl=run.skills[id]||0;return `<button type="button" class="draft-card" data-skill="${id}"><span class="draft-emoji">${s.icon}</span><strong>${esc(s.name)}</strong><small>${s.kind==='ultimate'?'ULTIMÁTKA · ':' ' }Úroveň ${lvl} → ${lvl+1}<br>${esc(s.desc)}</small></button>`}).join('');openModal('Vyber si vylepšení',`<p class="fine">Každý nový run má jiné možnosti. Výběrem se hra obnoví. Přetočení zbývá: <b>${run.rerolls||0}</b>.</p><div class="draft-cards">${cards}</div><div class="modal-actions"><button type="button" class="btn" data-action="autopick">Vybrat automaticky</button><button type="button" class="btn" data-action="reroll" ${(run.rerolls||0)<=0?'disabled':''}>⟳ Přetočit nabídku</button></div>`,'NOVÁ ÚROVEŇ')}
function showResult(won){
 const rift=run.mode==='rift',weekly=run.mode==='weekly',gauntlet=run.mode==='gauntlet',goal=bossesForRun(),headline=won?(rift?'Trhlina pokořena!':gauntlet?'Bossová zkouška dokončena!':weekly?'Týdenní zkouška dokončena!':'Lokace dokončena!'):run.loseReason==='timeout'?'Závěrečný boss odolal':run.loseReason==='retreat'?'Výprava ukončena':'Hrdina padl';
 const summary=won?(rift?`Pokořil jsi Astrální trhlinu stupně <b>${run.riftTier}</b>. Nejvyšší dosažený stupeň: ${meta.riftBest}.`:gauntlet?`Poražených bossů: <b>${run.bossesDefeated}/${goal}</b>. Požehnání: ${(run.blessings||[]).map(id=>GAUNTLET_BLESSINGS.find(x=>x.id===id)?.name).join(', ')||'žádná'}. Kletby: ${(run.curses||[]).map(id=>GAUNTLET_CURSES.find(x=>x.id===id)?.name).join(', ')||'žádné'}. Rekord: ${meta.gauntletBest}/${GAUNTLET_BOSSES}.`:weekly?`Dokončil jsi týdenní sestavu <b>${esc(run.weeklyKey)}</b>. Osobní rekord je ${fmt(meta.weeklyRecords[run.weeklyKey]?.score||0)} bodů.`:`Pokořil jsi všech <b>${goal} bossů</b> v oblasti ${esc(MAPS[run.map].name)}. ${run.map<meta.mapUnlocked?'Další mapa je odemčená.':'Oblast můžeš dál farmit.'}`):`Poraženo bossů: <b>${run.bossesDefeated||0}/${goal}</b>. Smrt nebo ústup nesmaže zlato, vybavení ani mistrovství. Další run můžeš zkusit s jiným buildem.`;
 const content=`<p>${summary}</p><div class="result-stats"><div><small>Délka výpravy</small><b>${mmss(run.time)}</b></div><div><small>${rift?'Stupeň trhliny':'Bossové'}</small><b>${rift?run.riftTier:`${run.bossesDefeated||0}/${goal}`}</b></div><div><small>Zabití nepřátelé</small><b>${fmt(run.kills)}</b></div><div><small>Získané zlato</small><b>${fmt(run.gold)}</b></div><div><small>Úroveň postavy</small><b>${fmt(run.level)}</b></div></div><div class="modal-actions"><button class="btn gold" data-action="newrun">⚔ Nový run</button><button class="btn" data-action="inventory">Prohlédnout loot</button></div>${settings.autoRuns?'<p class="fine">Automatický nový run za <b id="autoRestartCountdown">8</b> s. Kliknutím na „Prohlédnout loot“ automatické pokračování vypneš.</p>':''}`;
 openModal(headline,content,rift?'ENDGAME':gauntlet?'GAUNTLET':'LOKACE / PORÁŽKA');
}
function mmss(t){const v=Math.floor(t||0);return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`}
function openPanel(key){if(key==='market')return renderMarket();if(key==='guild')return renderGuild();if(key==='training')return renderTraining();if(key==='strategybook')return renderStrategyBook();if(key==='settings')return renderSettings();if(key==='merchant')return renderMerchant();if(key==='inventory')return renderInventory();if(key==='equipment')return renderEquipment();if(key==='talents')return renderTalents();if(key==='classes')return renderClasses();if(key==='prestige')return renderPrestige();if(key==='collection')return renderCollection();if(key==='achievements')return renderAchievements();if(key==='build')return renderBuild()}
function ensureDailyQuest(){const date=new Date().toISOString().slice(0,10);if(meta.hubDailyQuest?.date===date)return;const day=Math.floor(Date.parse(`${date}T00:00:00Z`)/86400000),kind=['kill','boss','finish'][day%3];meta.hubDailyQuest={date,kind,startKills:meta.kills||0,startBossKills:meta.totalBossKills||0,startRuns:meta.totalFinishedRuns||0,claimed:false};save(true)}
function dailyQuestProgress(){ensureDailyQuest();const q=meta.hubDailyQuest;if(q.kind==='kill')return {label:'Poraz 60 nepřátel',value:Math.max(0,meta.kills-q.startKills),goal:60,unit:'zabití'};if(q.kind==='boss')return {label:'Poraz jednoho bosse',value:Math.max(0,(meta.totalBossKills||0)-q.startBossKills),goal:1,unit:'boss'};return {label:'Odehraj jednu výpravu',value:Math.max(0,(meta.totalFinishedRuns||0)-q.startRuns),goal:1,unit:'výprava'}}
function renderGuild(){ensureDailyQuest();const q=dailyQuestProgress(),done=q.value>=q.goal&&!meta.hubDailyQuest.claimed,rank=meta.hirelingRank||0,cost=[700,1600,3200][rank]||0,required=2+rank*2;openModal('Cech dobrodruhů',`<div class="guild-npc"><span>🧭</span><div><b>Průvodkyně Mira</b><p>„Každá výprava má smysl. Vyber si drobný úkol a vrať se pro odměnu; úkoly jsou dobrovolné a nepropadají ti během dne.“</p></div></div><h3>Denní zakázka · ${meta.hubDailyQuest.date}</h3><div class="daily-quest-card"><div><b>${q.label}</b><small>Postup: ${Math.min(q.value,q.goal)} / ${q.goal} ${q.unit}</small></div>${meta.hubDailyQuest.claimed?'<span class="num">Odměna vyzvednuta</span>':done?'<button class="small-btn" data-action="claim-daily">Vyzvednout odměnu</button>':'<span class="num">V průběhu</span>'}</div><p class="fine">Odměna: 250 zlata, 3 úlomky duší a 2 runové úlomky. Každý den je dostupná jedna zakázka podle místního postupu.</p><h3>Najmi cechovního pomocníka</h3><div class="guild-npc"><span>🛡</span><div><b>${rank?`Pomocník · hodnost ${rank}/3`:'Volné místo'}</b><p>${rank?`Stálá podpora: +${rank*2.5}% poškození a +${rank}% zlata.`:'Pomocník doprovází všechny výpravy a zlepšuje poškození i nálezy.'} ${rank<3?`Další hodnost vyžaduje ${required} vítězných výprav.`:'Výcvik pomocníka je dokončen.'}</p></div>${rank<3?`<button class="small-btn" data-action="hireling" ${meta.wins<required||meta.gold<cost?'disabled':''}>${fmt(cost)} ◈</button>`:''}</div><p class="fine">Automatické kouzlení, další výprava, loot a rozklad se nastavují v pravidlech boje.</p><div class="modal-actions"><button class="btn" data-action="guild-automation">Otevřít automatizaci</button><button class="btn" data-action="guild-book">Otevřít knihu strategií</button></div>`,'CECH')}
function renderTraining(){openModal('Tréninkové nádvoří',`<p>Rozvíjej třídu a talenty, nebo si naprogramuj způsob boje. Tyto volby můžeš měnit mezi výpravami.</p><div class="training-destinations"><button class="hub-panel-card" data-action="training-classes"><span>♜</span><b>Třídy</b><small>Startovní kouzla a trvalé mistrovství.</small></button><button class="hub-panel-card" data-action="training-talents"><span>✦</span><b>Talenty</b><small>Trvalé statistiky pro tento cyklus.</small></button><button class="hub-panel-card" data-action="training-book"><span>📖</span><b>Kniha strategií</b><small>Profil, pohyb a výběr kouzel.</small></button></div><p class="fine">Aktuální profil: <b>${esc(PRESETS[settings.preset]?.name||'Vyvážený mág')}</b>. Automatický výběr lze vypnout tlačítkem pod bojištěm.</p>`,'TRÉNINK')}
function marketPrice(item){const rarity=Math.max(0,RARITIES.findIndex(r=>r.id===item.rarity));return Math.ceil((55+item.level*15+rarity*34)*(item.greaterAffix?1.5:1))}
function marketItemHtml(item){const stats=Object.entries(item.stats||{}).map(([k,v])=>`+${fmt(v)}${AFFIX_PERCENT.has(k)?'%':''} ${esc(AFFIX_NAMES[k]||k)}`).join(' · '),price=marketPrice(item);return `<article class="market-item"><div class="market-item-icon rarity-${item.rarity}">${SLOT_ICON[item.slot]}</div><div class="market-item-body"><b class="rarity-${item.rarity}">${esc(item.name)}</b><small>${esc(rarityName(item.rarity))} · ${esc(SLOT_NAMES[item.slot])} · Úroveň ${item.level}<br>${stats}${item.legend?`<br>✦ ${esc(LEGEND_EFFECTS[item.legend]||item.legend)}`:''}</small></div><button class="small-btn" data-market-buy="${esc(item.id)}" ${meta.gold<price||meta.inventory.length>=200?'disabled':''}>Koupit · ${fmt(price)} ◈</button></article>`}
function renderMarket(){if(marketStock===null)marketStock=Array.from({length:3},(_,i)=>{const map=meta.selectedMap,tier=runTier(MAPS[map].id),maxRarity=map>=4?'legendary':map>=2?'epic':'rare',rarity=i===0?null:i===1?(map>=3?'epic':'rare'):maxRarity;return makeItem(Math.max(1,meta.accountLevel),i===2?1:0,map,tier,rarity)});const rerollCost=Math.ceil(90*Math.pow(1.35,Math.min(meta.marketRerolls||0,12)));openModal('Tržiště výbavy',`<p>Kupec Soren vystavuje tři kusy z okolních oblastí. Nabídku můžeš přetočit; cena roste s každým přetočením. Inventář unese až 200 kusů.</p><div class="notice market-purse">Pokladnice: <b>${fmt(meta.gold)} zlata</b> · přetočení nabídky: ${meta.marketRerolls||0}×</div><div class="market-list">${marketStock.length?marketStock.map(marketItemHtml).join(''):'<div class="notice">Vše je prodáno. Přetoč nabídku, až budeš připraven utratit zlato.</div>'}</div><div class="modal-actions"><button class="btn gold" data-action="market-reroll" ${meta.gold<rerollCost?'disabled':''}>⟳ Přetočit nabídku · ${fmt(rerollCost)} zlata</button><button class="btn" data-action="market-quick-sell">Rozložit vše slabší než ${rarityName(settings.minKeep).toLowerCase()}</button></div><p class="fine">Obchod je osobní a lokální; hráčské výměny mezi účty potřebují server a nejsou v této verzi aktivní.</p>`,'TRH')}
function renderGuildQuick(){renderGuild()}
function showHubZone(id,fastTravel=false){const zone=HUB_ZONES.find(z=>z.id===id);if(!zone)return;hubSelection=id;if(fastTravel){hubPlayer.x=zone.x;hubPlayer.y=zone.y;hubPlayer.targetX=zone.x;hubPlayer.targetY=zone.y;interactHub(id,true)}else{hubPlayer.targetX=zone.x;hubPlayer.targetY=zone.y;updateHubUi()}}
function updateHubUi(){const box=$('hubZones');if(!box)return;const active=!$('pauseOverlay').classList.contains('hidden');$('hubWorldUi').classList.toggle('is-hidden',!active);if(!active)return;const zone=HUB_ZONES.find(z=>z.id===hubSelection)||HUB_ZONES[0],distance=Math.hypot(hubPlayer.x-zone.x,hubPlayer.y-zone.y);const renderKey=`${hubSelection}|${meta.hubVisited.join(',')}`;if(box.dataset.renderKey!==renderKey){box.dataset.renderKey=renderKey;box.innerHTML=HUB_ZONES.map(z=>`<button type="button" class="hub-hotspot ${z.id===hubSelection?'selected':''} ${meta.hubVisited.includes(z.id)?'visited':''}" data-hub-zone="${z.id}" style="left:${z.x}%;top:${z.y}%" aria-label="${z.label}: ${z.desc}"><span>${z.icon}</span><b>${z.label}</b></button>`).join('')}$('hubPlayer').style.left=`${hubPlayer.x}%`;$('hubPlayer').style.top=`${hubPlayer.y}%`;$('hubZoneName').textContent=zone.label;$('hubZoneHint').textContent=distance<3.5?`Jsi u místa. ${zone.desc} Stiskni Enter/E nebo tlačítko Navštívit.`:`Jdeš k místu. ${zone.desc} Pohyb: WASD / šipky.`;$('hubInteract').disabled=distance>=3.5;$('hubFastTravel').innerHTML=meta.hubVisited.filter(id=>id!==hubSelection).map(id=>{const z=HUB_ZONES.find(x=>x.id===id);return z?`<button type="button" data-hub-travel="${z.id}" title="Rychlé cestování: ${z.label}">${z.icon} ${z.label}</button>`:''}).join('')}
function stepHub(dt){if($('pauseOverlay').classList.contains('hidden'))return;meta.hubSeconds=(meta.hubSeconds||0)+dt;if(!$('modalBackdrop').classList.contains('hidden'))return;const dx=hubPlayer.targetX-hubPlayer.x,dy=hubPlayer.targetY-hubPlayer.y,d=Math.hypot(dx,dy),move=Math.min(d,32*dt);if(d>0){hubPlayer.x+=dx/d*move;hubPlayer.y+=dy/d*move}if(uiTimer<.08)updateHubUi()}
function hubMoveDirection(dx,dy){const from=HUB_ZONES.find(z=>z.id===hubSelection)||HUB_ZONES[0],candidates=HUB_ZONES.filter(z=>z.id!==from.id).map(z=>({z,dx:z.x-from.x,dy:z.y-from.y})).filter(o=>o.dx*dx+o.dy*dy>0);candidates.sort((a,b)=>{const av=(a.dx*dx+a.dy*dy)/Math.hypot(a.dx,a.dy),bv=(b.dx*dx+b.dy*dy)/Math.hypot(b.dx,b.dy);return bv-av});if(candidates[0])showHubZone(candidates[0].z.id)}
function interactHub(id=hubSelection,fastTravel=false){const zone=HUB_ZONES.find(z=>z.id===id);if(!zone)return;if(!fastTravel&&Math.hypot(hubPlayer.x-zone.x,hubPlayer.y-zone.y)>=3.5){showHubZone(id);notice(`Doraz k místu ${zone.label} a stiskni Enter nebo Navštívit.`);return}hubSelection=id;if(!meta.hubVisited.includes(id))meta.hubVisited.push(id);meta.hubZone=id;meta.hubInteractions=(meta.hubInteractions||0)+1;save(true);if(id==='portal'){document.querySelector('.maps-section')?.scrollIntoView({behavior:'smooth',block:'start'});hideIntro();return}if(id==='guild')return renderGuild();if(id==='forge')return renderMerchant();if(id==='market')return renderMarket();if(id==='training')return renderTraining();if(id==='stash')return renderInventory();}
function itemHtml(it,action='inventory'){
 const isEq=meta.equipped[it.slot]===it.id,req=it.level>meta.accountLevel,stats=Object.entries(it.stats||{}).map(([k,v])=>`+${fmt(v)}${AFFIX_PERCENT.has(k)?'%':''} ${esc(AFFIX_NAMES[k]||k)}`).join(' · '),legend=it.legend?`<br><span class="rarity-legendary">✦ ${esc(LEGEND_EFFECTS[it.legend]||it.legend)}</span>`:'',rerollCost=10+it.level*2+(it.rerolls||0)*5,runes=it.runes||[],runeword=runes.includes('ember')&&runes.includes('echo')?'Inferno Echo: druhé kouzlo přidá hoření.':'';
 const socketLine=Array.from({length:it.sockets||0},(_,i)=>`<span class="socket-gem ${runes[i]?'filled':''}" title="${runes[i]?RUNES[runes[i]]?.name||runes[i]:'Prázdný socket'}">${runes[i]?'◆':'◇'}</span>`).join('');
 const socketAction=action==='inventory'&&(it.sockets||0)>runes.length&&meta.runes.length?`<button class="small-btn" data-socket="${esc(it.id)}">Vložit ${esc(RUNES[meta.runes[0]]?.name||meta.runes[0])}</button>`:'';
 return `<div class="item"><div class="item-icon rarity-${it.rarity}">${SLOT_ICON[it.slot]}</div><div class="item-main"><div class="item-name rarity-${it.rarity}">${esc(it.name)}</div><div class="item-details">${esc(rarityName(it.rarity))} · ${esc(SLOT_NAMES[it.slot])} · Úroveň ${fmt(it.level)}${req?' <span class="warning">(zamčeno)</span>':''}${it.greaterAffix?`<br><span class="rarity-ancient">✦ Větší afix: ${esc(AFFIX_NAMES[it.greaterAffix]||it.greaterAffix)}</span>`:''}<br>${stats}${legend}${socketLine?`<br><span class="item-sockets">Sockety: ${socketLine}</span>`:''}${runeword?`<br><span class="rarity-mythic">✧ ${runeword}</span>`:''}${it.forged?`<br><span class="rarity-magic">✧ Kovářská úprava ${it.forged}/3</span>`:''}${it.rerolls?`<br>Přeroll affixů: ${it.rerolls}×`:''}</div></div><div class="item-actions">${isEq?'<span class="fine">Vybaveno</span>':`<button class="small-btn" data-equip="${esc(it.id)}" ${req?'disabled':''}>Vybavit</button>`}${socketAction}${action==='inventory'?`<button class="small-btn" data-forge="${esc(it.id)}" ${(it.forged||0)>=3||meta.essence<4+it.level*2+(it.forged||0)*4?'disabled':''}>Vylepšit ${4+it.level*2+(it.forged||0)*4} ✧</button><button class="small-btn" data-reroll="${esc(it.id)}" ${(it.locked||meta.essence<rerollCost)?'disabled':''}>Přeroll ${rerollCost} ✧</button>`:''}${action==='inventory'&&!isEq?`<button class="small-btn" data-lock="${esc(it.id)}">${it.locked?'🔒 Zamčeno':'🔓 Zamknout'}</button><button class="small-btn" data-salvage="${esc(it.id)}" ${it.locked?'disabled':''}>Rozložit</button>`:''}</div></div>`
}
function renderInventory(){const order={mythic:7,ancient:6,legendary:5,epic:4,rare:3,magic:2,common:1},score=i=>Object.entries(i.stats||{}).reduce((n,[k,v])=>n+v*(k==='hp'?.45:k==='atk'?2:1),0)+(i.legend?18:0),items=[...meta.inventory].filter(i=>inventoryView.filter==='all'||i.slot===inventoryView.filter);items.sort((a,b)=>inventoryView.sort==='level'?b.level-a.level||score(b)-score(a):inventoryView.sort==='rarity'?order[b.rarity]-order[a.rarity]||b.level-a.level:inventoryView.sort==='name'?a.name.localeCompare(b.name,'cs'):score(b)-score(a)||order[b.rarity]-order[a.rarity]||b.level-a.level);const equipped=SLOTS.map(slot=>{const it=meta.inventory.find(i=>i.id===meta.equipped[slot]);return `<section class="inventory-equipped-slot"><div class="inventory-slot-head"><b>${SLOT_ICON[slot]} ${SLOT_NAMES[slot]}</b>${it?`<button class="small-btn" data-unequip="${slot}">Sundat</button>`:''}</div>${it?itemHtml(it,'equipped'):'<div class="inventory-empty-slot">Prázdný slot</div>'}</section>`}).join('');const filters=[['all','Všechny sloty'],...SLOTS.map(s=>[s,SLOT_NAMES[s]])].map(([v,n])=>`<option value="${v}" ${inventoryView.filter===v?'selected':''}>${n}</option>`).join('');openModal(`Výbava a inventář (${meta.inventory.length}/200)`,`<p class="fine inventory-note">Výbava zůstává viditelná při procházení lootem. Porovnej slot a statistiky, vybav lepší kus, nebo roztřiď předměty.</p><div class="inventory-layout"><aside class="inventory-loadout"><h3>Vybaveno</h3>${equipped}</aside><section class="inventory-bag"><div class="inventory-toolbar"><label>Slot<select data-inv-filter>${filters}</select></label><label>Řadit podle<select data-inv-sort><option value="power" ${inventoryView.sort==='power'?'selected':''}>Síly předmětu</option><option value="rarity" ${inventoryView.sort==='rarity'?'selected':''}>Rarity</option><option value="level" ${inventoryView.sort==='level'?'selected':''}>Úrovně</option><option value="name" ${inventoryView.sort==='name'?'selected':''}>Názvu</option></select></label><span>${items.length} předmětů</span></div><div class="item-list inventory-item-list">${items.map(i=>itemHtml(i)).join('')||'<div class="empty">V tomto výběru nejsou žádné předměty.</div>'}</div></section></div>`,'VÝBAVA A LOOT')}
function ruleAvailable(index){return index<derived().ruleSlots}
function researchCost(k){const lv=meta.research[k];return Math.round((k==='attack'?90:k==='health'?70:160)*Math.pow(lv+1,1.65))}
function renderMerchant(){const cost=95+meta.accountLevel*35;const rows=[{id:'attack',name:'Výcvik arkanistů',desc:'+2 k poškození v tomto prestige cyklu.'},{id:'health',name:'Ochranné rituály',desc:'+9 maximálních životů v tomto prestige cyklu.'},{id:'loot',name:'Lepší poklady',desc:'+0,4 procentního bodu k šanci na loot.'}].map(r=>`<div class="talent-row"><div><strong>◈ ${r.name} <span class="num">${meta.research[r.id]}/20</span></strong><small>${r.desc}</small></div><button class="small-btn" data-research="${r.id}" ${meta.research[r.id]>=20||meta.gold<researchCost(r.id)?'disabled':''}>${fmt(researchCost(r.id))} ◈</button></div>`).join(''),runeRows=Object.entries(RUNES).map(([id,r])=>`<div class="talent-row"><div><strong>◇ ${r.name}</strong><small>${Object.entries(r.stats).map(([k,v])=>`+${v} ${AFFIX_NAMES[k]||k}`).join(' · ')}</small></div><button class="small-btn" data-craft-rune="${id}" ${meta.runeshards<3?'disabled':''}>Vyrobit · 3 úlomky</button></div>`).join('');openModal('Kovárna a výzkum',`<p>Pokladnice: <b>${fmt(meta.gold)} zlata</b> · ${fmt(meta.bossSigils||0)} boss sigilů · ${fmt(meta.riftDust||0)} prachu trhlin · ${fmt(meta.soulFragments||0)} úlomků duší.</p><div class="notice"><b>Tajemná truhla:</b> náhodný předmět odpovídající tvému mistrovství. Jeho vlastnosti zjistíš až po nákupu.<div class="modal-actions"><button class="btn gold" data-action="chest" ${meta.gold<cost||meta.inventory.length>=200?'disabled':''}>Otevřít truhlu za ${fmt(cost)} zlata</button></div></div><div class="menu-card-grid"><div class="notice"><b>Cílená relikvie</b><p>Bossové sigily zaručí legendární předmět.</p><button class="small-btn" data-action="sigil-craft" ${meta.bossSigils<12||meta.inventory.length>=200?'disabled':''}>Vyrobit · 12 sigilů</button></div><div class="notice"><b>Rift truhla</b><p>Prastarý nebo lepší předmět z pozdních oblastí.</p><button class="small-btn" data-action="rift-craft" ${meta.riftDust<20||meta.inventory.length>=200?'disabled':''}>Otevřít · 20 prachu</button></div></div><h3>Alchymie · ${meta.alchemyTonics||0}/3 elixírů</h3><div class="notice"><b>Elixír vitality</b><p>Uvaření stojí 120 esencí. Jeden elixír před běžnou výpravou zvýší maximální zdraví o 15 %. Týdenní a zvláštní zkoušky zůstávají beze změny.</p><button class="small-btn" data-action="brew-tonic">Uvařit elixír · 120 esencí</button></div><h3>Kovář duší · ${fmt(meta.soulFragments||0)} úlomků</h3><div class="menu-card-grid"><div class="talent-row"><div><strong>Síla duše <span class="num">${meta.soulUpgrades?.force||0}/10</span></strong><small>+2 % poškození za úroveň; cena 15 úlomků.</small></div><button class="small-btn" data-soul-upgrade="force" ${meta.soulFragments<15||(meta.soulUpgrades?.force||0)>=10?'disabled':''}>Vylepšit</button></div><div class="talent-row"><div><strong>Duševní ochrana <span class="num">${meta.soulUpgrades?.ward||0}/10</span></strong><small>+3 % maximálních životů za úroveň; cena 15 úlomků.</small></div><button class="small-btn" data-soul-upgrade="ward" ${meta.soulFragments<15||(meta.soulUpgrades?.ward||0)>=10?'disabled':''}>Vylepšit</button></div></div><h3>Výzkum pro tento cyklus</h3><div class="menu-card-grid">${rows}</div><h3>Runová dílna · ${meta.runeshards||0} úlomků</h3><p class="fine">Vyrobené runy můžeš vložit do volného socketu na vzácné nebo lepší výbavě. Ember + Echo na jednom kusu vytvoří runové slovo Inferno Echo.</p><div class="menu-card-grid rune-grid">${runeRows}</div><p class="fine">Výzkum a zlato se resetují při prestige. Inventář a legendární předměty zůstávají.</p>`,'KOVÁRNA') }
function renderEquipment(){renderInventory()}
function renderTalents(){const rows=Object.entries(TALENTS).map(([id,t])=>`<div class="talent-row"><div><strong>${t.icon} ${t.name} <span class="num">${meta.talents[id]}/${t.max}</span></strong><small>${t.desc}</small></div><button class="small-btn" data-talent="${id}" ${talentPoints()<=0||meta.talents[id]>=t.max?'disabled':''}>+ Bod</button></div>`).join('');openModal('Strom talentů',`<p>Volné talentové body: <b>${talentPoints()}</b>. Za každou novou úroveň mistrovství získáš jeden bod. Body jsou trvalé do prestige.</p><div class="menu-card-grid">${rows}</div><p class="fine">Každá třída má navíc vlastní trvalé milníky v panelu Třídy.</p>`,'MISTROVSTVÍ')}
function renderClasses(){const rows=Object.entries(CLASSES).map(([id,cls])=>{const p=meta.classMastery[id],need=classMasteryNeed(p.level),milestones=cls.milestones.map((node,index)=>`<small>${p.level>=(index+1)*10?'✓':'◇'} Úroveň ${(index+1)*10}: ${node.text}</small>`).join('');return `<div class="talent-row"><div><strong>${cls.icon} ${cls.name} <span class="num">${p.level}/50</span></strong><small>${cls.desc}</small><div class="meter gold class-xp"><div style="width:${p.level>=50?100:clamp(p.xp/need*100,0,100)}%"></div></div><small>${p.level>=50?'Mistrovství dokončeno':`${fmt(p.xp)} / ${fmt(need)} XP do další úrovně`}</small>${milestones}</div><button class="small-btn" data-class="${id}" ${run?.active||meta.selectedClass===id?'disabled':''}>${meta.selectedClass===id?'Vybráno':'Vybrat'}</button></div>`}).join('');openModal('Třídy a jejich mistrovství',`<p>Každá třída začíná jiným kouzlem a má vlastní trvalé bonusy i milníky mistrovství. Zkušenosti získává pouze třída použitá v dané výpravě.</p><div class="menu-card-grid">${rows}</div>`,'POSTAVA')}
function prestigeEligible(){return meta.cycleWins>=4&&meta.accountLevel>=9&&meta.mapUnlocked>=1}
function prestigeGain(){return Math.max(1,1+Math.floor(meta.cycleWins/2)+Math.floor(meta.accountLevel/10))}
function doPrestige(){if(!prestigeEligible()||run?.active)return;meta.echoes+=prestigeGain();meta.prestige++;meta.gold=120;meta.essence=0;meta.accountLevel=1;meta.accountXp=0;meta.cycleWins=0;meta.mapTrials=Object.fromEntries(MAPS.map(m=>[m.id,0]));meta.mapUnlocked=0;meta.selectedMap=0;meta.talents={might:0,heart:0,swift:0,fortune:0,sage:0};meta.research={attack:0,health:0,loot:0};meta.difficulty=0;log('Astrální znovuzrození dokončeno. Inventář, třídy a astrální strom zůstaly zachovány.','rare');save(true);renderPrestige();updateUI()}
function doTranscendence(){const available=Math.max(0,Math.floor((meta.riftBest||0)/10)-(meta.transcendedAt||0));if(run?.active||available<1)return;meta.transcendencePoints+=available;meta.transcendedAt=Math.floor(meta.riftBest/10);meta.difficulty=0;meta.mapTrials=Object.fromEntries(MAPS.map(m=>[m.id,0]));meta.mapUnlocked=0;meta.selectedMap=0;log(`Transcendence: získáno ${available} bodů. Codex, legendární objevy, kosmetika, vybavení a mistrovství tříd zůstávají.`,'rare');save(true);renderPrestige();updateUI()}
function renderPrestige(){const ok=prestigeEligible(),html=Object.entries(ASTRAL_BRANCHES).map(([branch,ids])=>`<section class="astral-branch"><h3>${branch}</h3><div class="menu-card-grid astral-grid">${ids.map(id=>{const a=ASTRAL[id],l=meta.astral[id]||0,cost=l+1;return `<div class="astral-row"><div><strong>${a.icon} ${a.name} <span class="num">${l}/${a.max}</span></strong><small>${a.desc}</small></div><button class="small-btn" data-astral="${id}" ${meta.echoes<cost||l>=a.max?'disabled':''}>${cost} ✦</button></div>`}).join('')}</div></section>`).join('');const tx=meta.transcendence||{force:0,ward:0,fortune:0},available=Math.max(0,Math.floor((meta.riftBest||0)/10)-(meta.transcendedAt||0)),txRows=[['force','Síla za hranou','+5 % poškození za bod'],['ward','Nezlomná duše','+5 % maximálních životů za bod'],['fortune','Věštecká kořist','+3 % kvality kořisti za bod']].map(([id,name,desc])=>`<div class="talent-row"><div><strong>✧ ${name} <span class="num">${tx[id]||0}/10</span></strong><small>${desc}</small></div><button class="small-btn" data-transcend-upgrade="${id}" ${meta.transcendencePoints<1||(tx[id]||0)>=10?'disabled':''}>1 bod</button></div>`).join('');
 openModal('Astrální znovuzrození',`<p>Prestige: <b>${meta.prestige}</b> · Astrální ozvěny: <b>${fmt(meta.echoes)}</b> · Transcendence: <b>${meta.transcendencePoints||0} bodů</b></p><div class="notice">${available?`Apex Rift dovoluje Transcendenci: získáš ${available} bodů.`:`Další Transcendence po dosažení Riftu ${((meta.transcendedAt||0)+1)*10}.`}</div><div class="modal-actions"><button class="btn gold" data-action="transcend" ${available<1||run?.active?'disabled':''}>✧ Provést Transcendenci · resetovat Nightmare postup</button></div><h3>Trvalý strom Transcendence</h3><div class="menu-card-grid">${txRows}</div><div class="notice">${ok?`Znovuzrození je dostupné. Získáš <b>${prestigeGain()} astrálních ozvěn</b>.`:`Potřebuješ alespoň <b>4 vítězné výpravy</b>, mistrovství <b>úrovně 9</b> a odemčené katakomby.<br>Aktuální stav: ${meta.cycleWins}/4 vítězství, úroveň ${meta.accountLevel}/9, katakomby ${meta.mapUnlocked>=1?'ano':'ne'}.`}</div><p class="fine">Prestige resetuje zlato, esence, mistrovství postavy, běžné talenty, výzkum a odemčené mapy. Mistrovství tříd, inventář a astrální uzly zůstávají.</p><div class="modal-actions"><button class="btn gold" data-action="prestige" ${!ok?'disabled':''}>✦ Provést prestige (+${prestigeGain()} ozvěn)</button></div>${html}`,'PRESTIGE')}
function renderAchievements(){const rows=ACHIEVEMENTS.map(a=>{const done=!!meta.achievements[a.id];return `<div class="talent-row"><div><strong>${done?'🏅':'🔒'} ${a.name}</strong><small>${a.desc} · Odměna: ${a.cosmeticName}</small></div><span class="num">${done?'Odemčeno':'Zamčeno'}</span></div>`}).join(''),cosmetics=[...new Set(['plain',...meta.cosmetics])],names={plain:'Poutnická',frost:'Ledová',gold:'Zlatá',astral:'Astrální',emerald:'Smaragdová'},buttons=cosmetics.map(c=>`<button class="small-btn" data-cosmetic="${c}" ${meta.selectedCosmetic===c?'disabled':''}>${names[c]||c} aura</button>`).join('');openModal('Achievementy a kosmetika',`<p class="fine">Achievementy odemykají pouze vzhledové odměny a neslouží jako další měna.</p><div class="menu-card-grid">${rows}</div><h3>Portrétní aura</h3><div class="modal-actions">${buttons}</div><h3>Poslední výpravy</h3><div class="menu-card-grid">${meta.runHistory.slice(-8).reverse().map(r=>`<div class="talent-row"><div><strong>${esc(MAPS.find(m=>m.id===r.map)?.name||r.map)} · ${esc(CLASSES[r.classId]?.name||r.classId)}</strong><small>${mmss(r.duration)} · ${fmt(r.kills)} zabití · ${r.bosses} bossů · ${fmt(r.gold)} zlata</small></div><span class="num">${r.won?'Vítězství':'Neúspěch'}</span></div>`).join('')||'<p class="fine">Historie se naplní po prvním runu.</p>'}</div><p class="fine">Uloženo je posledních 40 výprav. Historii lze přenést exportem uložené hry JSON.</p>`,'OSOBNÍ CÍLE')}
function renderCollection(){const w=MAPS.map((m,i)=>`<div class="talent-row"><div><strong>${m.icon} ${m.name}</strong><small>Boss: ${m.boss}</small></div><span class="num">${meta.bosses[m.id]||0}×</span></div>`).join('');const rar=RARITIES.map(r=>`<span class="rarity-${r.id}">${r.name}: ${meta.collection[r.id]||0}</span>`).join(' · ');openModal('Kronika objevů',`<p>Celkem zabito <b>${fmt(meta.kills)}</b> nepřátel, dokončeno <b>${fmt(meta.wins)}</b> výprav. Počet prestiží: <b>${meta.prestige}</b>.</p><div class="menu-card-grid">${w}</div><h3>Objevené předměty</h3><p>${rar}</p><p class="fine">Evoluce kouzel a bestiář se rozšiřují s dalšími výpravami.</p>`,'SBÍRKA')}
function renderBuild(){renderStrategyBook()}
function renderStrategyBook(){const profile=PRESETS[settings.preset]||PRESETS.balanced,weights=PROFILE_TAG_WEIGHTS[settings.preset]||{},focus=Object.entries(weights).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([tag])=>TAG_LABELS[tag]||tag).join(' · '),profiles=Object.entries(PRESETS).map(([id,p])=>{const tags=Object.entries(PROFILE_TAG_WEIGHTS[id]||{}).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([tag])=>TAG_LABELS[tag]||tag).join(' · ');return `<article class="strategy-card ${id===settings.preset?'is-selected':''}"><div class="strategy-card-top"><span>${id===settings.preset?'✓':'✧'}</span><b>${esc(p.name)}</b></div><p>${esc(p.desc)}</p><small>Priorita: ${esc(tags||'volný výběr')}</small><button class="small-btn" data-preset="${id}" ${id===settings.preset?'disabled':''}>${id===settings.preset?'Aktivní profil':'Použít profil'}</button></article>`}).join(''),skills=Object.entries(SKILLS).map(([id,s])=>`<div class="talent-row"><div><strong>${s.icon} ${esc(s.name)}</strong><small>${esc(s.desc)}<br>Role: ${(s.tags||[]).map(tag=>TAG_LABELS[tag]||tag).join(' · ')||'všestranná'}${run?.skills[id]?` · vybráno ${run.skills[id]}/${s.max}`:''}</small></div><span class="num">${s.kind==='active'?'Aktivní':s.kind==='passive'?'Pasivní':s.kind==='ultimate'?'Ultimátka':'Úprava'}</span></div>`).join('');openModal('Kniha strategií a kouzel',`<section class="strategy-intro"><span class="book-mark">📖</span><div><h3>Jak fungují bojové profily</h3><p>Profil řídí automatický výběr při každém zvýšení úrovně. Nezamyká kouzla: upravuje jejich pořadí podle role, štítků kouzel a možnosti dokončit synergie. Kouzla se sesílají sama, jakmile doběhne jejich obnova.</p><p><b>Aktuálně:</b> ${esc(profile.name)} — ${esc(profile.desc)}</p><p><b>Hlavní priority:</b> ${esc(focus||'vyvážené možnosti')}.</p></div></section><div class="notice"><b>Jak si vybrat:</b> Bezpečný farmář a Strážce lépe ustojí delší boj; Lovec bossů a Průlom trhlinou tlačí na poškození; Sběrač relikvií se soustředí na zkušenosti a sběr. Experimentátor volí náhodně. Ostatní archetypy mají specializované váhy. Profil můžeš kdykoliv změnit i během výpravy.</div><div class="strategy-guide-grid"><article><b>⚔ Styl pohybu</b><p>Kroužit a uhýbat drží odstup. Tlačit na cíl se přiblíží. Obíhat opisuje těsný kruh. Držet střed omezuje vzdálení od arény. Cíl a nebezpečné zóny nastavíš zvlášť v Automatizaci.</p></article><article><b>✦ Výběr kouzel</b><p>Automatický výběr upřednostní profilové tagy, už rozvinutá kouzla a dvojice potřebné k evoluci. Vypnutím automatiky si nabídku při postupu zvolíš ručně.</p></article><article><b>◇ Synergie</b><p>Řetězový blesk + Ledová nova → Mrazová bouře. Ohnivá koule + Meteor → Pekelný déšť. Duševní střely + Astrální orbity → Astrální legie. Zvyšuj obě kouzla, abys evoluci dokončil.</p></article></div><h3>Vyber bojový profil</h3><div class="strategy-profiles">${profiles}</div><h3>Kniha kouzel</h3><div class="menu-card-grid">${skills}</div><p class="fine">Profily pouze upravují váhy automatického výběru. Vybavení, Combat Rules a nabídka úrovně se nastavují samostatně.</p>`,'KNIHA STRATEGIÍ')}
function renderSettings(){
 const rules=[['targetPriority','Priorita cíle',0,[['nearest','Nejbližší'],['lowHp','Nejméně zdraví'],['elite','Elita'],['boss','Boss'],['ranged','Ranged nepřítel']]],['movement','Pohyb',1,[['kite','Kroužit a uhýbat'],['aggressive','Tlačit na cíl'],['orbit','Obíhat cíl'],['center','Držet střed']]],['skillTrigger','Spouštění kouzel',2,[['cooldown','Při připraveném cooldownu'],['boss','Pouze u bosse'],['elite','Pouze u elity nebo bosse'],['crowd','Při 6+ nepřátelích']]],['potionThreshold','Lektvar zdraví',3,[['70','Pod 70 %'],['50','Pod 50 %'],['30','Pod 30 %'],['0','Nepoužívat automaticky']]],['ultimatePolicy','Ultimátka',4,[['boss','Šetřit na bosse'],['elite','Na elity a bossy'],['emergency','Použít při ohrožení'],['always','Použít ihned']]],['dangerZones','Nebezpečné zóny',5,[['strict','Přísně uhýbat'],['normal','Vyváženě'],['greedy','Ignorovat menší hrozby']]],['lootFilter','Sbírání kořisti',6,[['all','Vše'],['rare','Vzácné a lepší'],['legendary','Legendární a lepší']]],['salvageFilter','Filtr rozkladu',7,[['common','Obyčejné'],['magic','Magické a horší'],['rare','Vzácné a horší']]]];
 const ruleRows=rules.map(([key,label,index,opts])=>`<div class="setting-row ${ruleAvailable(index)?'':'rule-locked'}"><label for="rule-${key}">${label}${ruleAvailable(index)?'':` · odemkne se při úrovni ${index<5?10:30}`}</label><select id="rule-${key}" data-setting="${key}" ${ruleAvailable(index)?'':'disabled'}>${opts.map(([value,name])=>`<option value="${value}" ${String(settings[key])===value?'selected':''}>${name}</option>`).join('')}</select></div>`).join('');
 openModal('Automatizace a data',`<p class="fine">Pravidla boje postupně odemyká mistrovství. Základní tři sloty jsou dostupné od začátku, další po dosažení úrovní 10 a 30.</p><h3>Combat Rules · ${derived().ruleSlots}/8 slotů</h3>${ruleRows}<h3>Základní automatizace</h3><div class="setting-row"><label for="settingAutoSkills">Automaticky volit kouzla</label><input type="checkbox" id="settingAutoSkills" data-setting="autoSkills" ${settings.autoSkills?'checked':''}></div><div class="setting-row"><label for="settingAutoRuns">Automaticky začít další run</label><input type="checkbox" id="settingAutoRuns" data-setting="autoRuns" ${settings.autoRuns?'checked':''}></div><div class="setting-row"><label for="settingAutoSalvage">Automaticky rozkládat loot podle rarity</label><input type="checkbox" id="settingAutoSalvage" data-setting="autoSalvage" ${settings.autoSalvage?'checked':''}></div><div class="setting-row"><label for="settingAutoCraftRunes">Automaticky vyrábět náhodné runy (ponechat 9 úlomků)</label><input type="checkbox" id="settingAutoCraftRunes" data-setting="autoCraftRunes" ${settings.autoCraftRunes?'checked':''}></div><div class="setting-row"><label for="settingMinKeep">Ponechat raritu alespoň</label><select id="settingMinKeep" data-setting="minKeep">${RARITIES.map(r=>`<option value="${r.id}" ${r.id===settings.minKeep?'selected':''}>${r.name}</option>`).join('')}</select></div><div class="setting-row"><label for="settingCombat">Záložní styl pohybu</label><select id="settingCombat" data-setting="combat"><option value="balanced" ${settings.combat==='balanced'?'selected':''}>Vyvážený</option><option value="aggressive" ${settings.combat==='aggressive'?'selected':''}>Agresivní</option><option value="defensive" ${settings.combat==='defensive'?'selected':''}>Obranný</option></select></div><div class="setting-row"><label for="settingFps">Limit FPS (nižší zátěž)</label><select id="settingFps" data-setting="fps"><option value="30" ${settings.fps===30?'selected':''}>30 FPS</option><option value="60" ${settings.fps===60?'selected':''}>60 FPS</option></select></div><h3>Lokální analytika</h3><p class="fine">Statistiky zůstávají v tomto prohlížeči. Souhrn můžeš exportovat jako JSON; globální hráčská data bez serveru nejsou k dispozici.</p><div class="modal-actions"><button class="btn" data-action="telemetry-export">↓ Export telemetry JSON</button></div><h3>Zálohování</h3><div class="modal-actions"><button class="btn gold" data-action="export">↓ Stáhnout zálohu JSON</button><button class="btn" data-action="import">↑ Nahrát uloženou hru</button><button class="btn warn" data-action="reset">Vymazat celý postup</button></div><p class="fine">Export obsahuje vybavení, inventář, talenty, prestige, nastavení a aktivní run. Neobsahuje informace z jiných webů ani účtů.</p>`,'NASTAVENÍ')
}
